/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  patients: Model<Stored>
  rooms: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'patients' collection. */
  const patients = new Schema(
    {
      name: { type: String, required: true, maxlength: 80, minlength: 2 },
      birth: { type: Date, required: true },
      weight: Number,
      balance: Schema.Types.Decimal128,
      document: String,
      photo: Buffer,
      visits: { type: Number, required: true, min: 0 },
      blood: { type: String, enum: ['A', 'B', 'O'] },
      contacts: { type: [new Schema({ kind: { type: String, enum: ['phone', 'email'], required: true }, value: { type: String, required: true } }, { _id: false, strict: false, minimize: false })], default: undefined, required: true },
      insurance: new Schema({ company: String, since: Date }, { _id: false, strict: false, minimize: false }),
      version: Number,
    },
    { collection: 'patients', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  patients.index({ document: 1 }, { unique: true, name: 'ux_document' })
  patients.index({ birth: 1 })

  /** The 'rooms' collection. */
  const rooms = new Schema(
    {
      code: { type: String, required: true },
      beds: Schema.Types.BigInt,
    },
    { collection: 'rooms', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )

  return {
    patients: connection.model<Stored>('Patient', patients as unknown as Schema<Stored>),
    rooms: connection.model<Stored>('Room', rooms as unknown as Schema<Stored>),
  }
}

