/** Repository of the "patients" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { randomBytes } from 'node:crypto'
import { isObjectId, plain, refusal, type Db } from '../database.js'
import { Patient } from '../entities/patient.js'
import type { Stored } from '../models.js'
import type { Page } from '../paging.js'

/** Where patients rows are kept. Services depend only on this interface. */
export interface PatientRepository {
  findById(id: string): Promise<Patient | null>
  list(offset?: number, limit?: number): Promise<Page<Patient>>
  findByDocument(document: string): Promise<Patient | null>
  findAllByBirth(birth: Date): Promise<Patient[]>
  insert(entity: Patient): Promise<Patient>
  update(entity: Patient): Promise<Patient>
  delete(entity: Patient): Promise<void>
  addContact(id: string, contact: { kind: string; value: string }): Promise<Patient | null>
  removeContact(id: string, position: number, size: number): Promise<Patient | null>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Patient): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Patient, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Patient): Stored {
  return {
    name: entity.name,
    birth: entity.birth,
    weight: entity.weight,
    balance: entity.balance,
    document: entity.document,
    photo: entity.photo,
    visits: entity.visits,
    blood: entity.blood,
    contacts: entity.contacts,
    insurance: entity.insurance,
    version: entity.version,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Patient): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Patient of a document; a field it does not have is null. */
function toEntity(document: Stored): Patient {
  const entity = Object.assign(new Patient(), {
    id: (plain(document._id) ?? null) as string,
    name: (plain(document.name) ?? null) as string,
    birth: (plain(document.birth) ?? null) as Date,
    weight: (plain(document.weight) ?? null) as number | null,
    balance: (plain(document.balance) ?? null) as string | null,
    document: (plain(document.document) ?? null) as string | null,
    photo: (plain(document.photo) ?? null) as Buffer | null,
    visits: (plain(document.visits) ?? null) as number,
    blood: (plain(document.blood) ?? null) as string | null,
    contacts: (plain(document.contacts) ?? null) as { kind: string; value: string }[],
    insurance: (plain(document.insurance) ?? null) as { company?: string | null; since?: Date | null } | null,
    version: (plain(document.version) ?? null) as number | null,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Patient): Stored {
  const values: Stored = {
    _id: entity.id,
    name: entity.name,
    birth: entity.birth,
    weight: entity.weight,
    balance: entity.balance,
    document: entity.document,
    photo: entity.photo,
    visits: entity.visits,
    blood: entity.blood,
    contacts: entity.contacts,
    insurance: entity.insurance,
    version: entity.version,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Patient): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps patients documents in the database, through Mongoose. Every write is stored at once. */
export class MongoPatientRepository implements PatientRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Patient | null> {
    if (!isObjectId(id)) return null
    const foundDocument = await this.db.models.patients.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Patient>> {
    const documents = await this.db.models.patients.find({}).sort({ _id: 1 }).skip(offset).limit(limit).session(this.session).lean<Stored[]>()
    const total = await this.db.models.patients.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** The row with this document, or null. */
  async findByDocument(document: string): Promise<Patient | null> {
    const foundDocument = await this.db.models.patients.findOne({ document }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** Rows with this birth, by primary key. */
  async findAllByBirth(birth: Date): Promise<Patient[]> {
    return (await this.db.models.patients.find({ birth }).sort({ _id: 1 }).session(this.session).lean<Stored[]>()).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Patient): Promise<Patient> {
    try {
      const [document] = await this.db.models.patients.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Patient', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Patient): Promise<Patient> {
    try {
      await this.db.models.patients.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Patient', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Patient): Promise<void> {
    try {
      await this.db.models.patients.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Patient', error)
    }
  }

  /** Adds an item to contacts, and returns the row as it is then, or null when there is none. */
  async addContact(id: string, contact: { kind: string; value: string }): Promise<Patient | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.patients
        .findOneAndUpdate({ _id: id }, { $push: { contacts: contact }, $inc: { version: 1 } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Patient', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from contacts that has this size, and returns the row as it is then, or null when there is none. */
  async removeContact(id: string, position: number, size: number): Promise<Patient | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.patients
        .findOneAndUpdate({ _id: id, contacts: { $size: size } }, [{ $set: { contacts: { $concatArrays: [{ $slice: ['$contacts', position] }, { $slice: ['$contacts', position + 1, size] }] }, version: { $add: ['$version', 1] } } }], { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Patient', error)
    }
    return changed === null ? null : toEntity(changed)
  }
}

/** Keeps patients rows in memory, for tests and for trying the services without a database. */
export class MemoryPatientRepository implements PatientRepository {
  private readonly rows = new Map<string, Patient>()

  private visible(): Patient[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Patient | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Patient>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** The row with this document, or null. */
  async findByDocument(document: string): Promise<Patient | null> {
    return this.visible().find((row) => row.document === document) ?? null
  }

  /** Rows with this birth, by primary key. */
  async findAllByBirth(birth: Date): Promise<Patient[]> {
    return this.visible().filter((row) => row.birth === birth)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Patient): Promise<Patient> {
    if (entity.id === undefined) entity.id = randomBytes(12).toString('hex')
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

