/** Repository of the "rooms" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { randomBytes } from 'node:crypto'
import { isObjectId, plain, refusal, type Db } from '../database.js'
import { Room } from '../entities/room.js'
import type { Stored } from '../models.js'
import type { Page } from '../paging.js'

/** Where rooms rows are kept. Services depend only on this interface. */
export interface RoomRepository {
  findById(id: string): Promise<Room | null>
  list(offset?: number, limit?: number): Promise<Page<Room>>
  insert(entity: Room): Promise<Room>
  update(entity: Room): Promise<Room>
  delete(entity: Room): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Room): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Room, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Room): Stored {
  return {
    code: entity.code,
    beds: entity.beds,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Room): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Room of a document; a field it does not have is null. */
function toEntity(document: Stored): Room {
  const entity = Object.assign(new Room(), {
    id: (plain(document._id) ?? null) as string,
    code: (plain(document.code) ?? null) as string,
    beds: (plain(document.beds) ?? null) as number | null,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Room): Stored {
  const values: Stored = {
    _id: entity.id,
    code: entity.code,
    beds: entity.beds,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Room): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps rooms documents in the database, through Mongoose. Every write is stored at once. */
export class MongoRoomRepository implements RoomRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Room | null> {
    if (!isObjectId(id)) return null
    const foundDocument = await this.db.models.rooms.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Room>> {
    const documents = await this.db.models.rooms.find({}).sort({ _id: 1 }).skip(offset).limit(limit).session(this.session).lean<Stored[]>()
    const total = await this.db.models.rooms.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Room): Promise<Room> {
    try {
      const [document] = await this.db.models.rooms.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Room', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Room): Promise<Room> {
    try {
      await this.db.models.rooms.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Room', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Room): Promise<void> {
    try {
      await this.db.models.rooms.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Room', error)
    }
  }
}

/** Keeps rooms rows in memory, for tests and for trying the services without a database. */
export class MemoryRoomRepository implements RoomRepository {
  private readonly rows = new Map<string, Room>()

  private visible(): Room[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Room | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Room>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Room): Promise<Room> {
    if (entity.id === undefined) entity.id = randomBytes(12).toString('hex')
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Room): Promise<Room> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Room): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

