/** Operations on patients: what each one checks before it writes. */
import { problems, type Rule } from '../documents.js'
import { Patient } from '../entities/patient.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['name', 'birth', 'weight', 'balance', 'document', 'photo', 'visits', 'blood', 'contacts', 'insurance', 'version'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  contacts: { items: { fields: { kind: { required: true, values: ['phone', 'email'] }, value: { required: true } } } },
  insurance: { fields: { company: {}, since: {} } },
} satisfies Record<string, Rule>

/** Operations on patients. Repositories commit every write. */
export class PatientService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "patients" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Patient | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Patient' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'version'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.name
      if (value == null) {
        if (creating || 'name' in values) errors.push({ field: 'name', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 80) errors.push({ field: 'name', message: 'is longer than 80 characters' })
        if (!(String(value).length >= 2)) errors.push({ field: 'name', message: 'must have >= 2 characters' })
      }
    }
    {
      const value = values.birth
      if (value == null) {
        if (creating || 'birth' in values) errors.push({ field: 'birth', message: 'is required' })
      }
    }
    {
      const value = values.visits
      if (value == null) {
        if (creating || 'visits' in values) errors.push({ field: 'visits', message: 'is required' })
      } else {
        if (!(Number(value) >= 0)) errors.push({ field: 'visits', message: 'must be >= 0' })
      }
    }
    {
      const value = values.blood
      if (value != null) {
        if (!['A', 'B', 'O'].includes(value as never)) errors.push({ field: 'blood', message: 'must be one of: A, B, O' })
      }
    }
    {
      const value = values.contacts
      if (value == null) {
        if (creating || 'contacts' in values) errors.push({ field: 'contacts', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.contacts, 'contacts'))
      }
    }
    {
      const value = values.insurance
      if (value != null) {
        errors.push(...problems(value, DOCUMENTS.insurance, 'insurance'))
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Patient', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Patient | null): Promise<void> {
    {
      const document = ('document' in values ? values.document : current?.document) as string | null | undefined
      if (document != null) {
        const other = await uow.patients.findByDocument(document)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Patient', 'document is already taken', ['document'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Patient | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Patient with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Patient> {
    const entity = await uow.patients.findById(id)
    if (entity === null) throw new NotFoundError('Patient', id)
    return entity
  }

  /** Stores a new Patient after checking it. */
  async createPatient(patient: Patient): Promise<Patient> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (patient as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.patients.insert(patient)
      return created
    })
  }

  /** The Patient with this key; NotFoundError when there is none. */
  async getPatient(id: string): Promise<Patient> {
    return await this.find(this.uow, id)
  }

  /** A page of patients, by primary key. */
  async listPatients(offset = 0, limit = 50): Promise<Page<Patient>> {
    return this.uow.patients.list(offset, limit)
  }

  /** Changes the given values of a Patient, read at `version`. */
  async updatePatient(id: string, changes: Partial<Patient>, version: number): Promise<Patient> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Patient', 'was changed by someone else since it was read', ['version'])
      await this.check(uow, values, current)
      Object.assign(current, values)
      current.version = version + 1
      const updated = await uow.patients.update(current)
      return updated
    })
  }

  /** Deletes a Patient. */
  async deletePatient(id: string, version: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Patient', 'was changed by someone else since it was read', ['version'])
      await uow.patients.delete(current)
    })
  }

  /** The Patient with this document, or null. */
  async findPatientByDocument(document: string): Promise<Patient | null> {
    return await this.uow.patients.findByDocument(document)
  }

  /** Adds an item to contacts, read at `version`. */
  async addContact(id: string, contact: { kind: string; value: string }, version: number): Promise<Patient> {
    const errors = problems([contact], DOCUMENTS.contacts, 'contacts')
    if (errors.length > 0) throw new ValidationFailedError('Patient', errors)
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Patient', 'was changed by someone else since it was read', ['version'])
      const updated = await uow.patients.addContact(id, contact)
      if (updated === null) throw new NotFoundError('Patient', id)
      return updated
    })
  }

  /** Removes an item from contacts, by its position, read at `version`. */
  async removeContact(id: string, position: number, version: number): Promise<Patient> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Patient', 'was changed by someone else since it was read', ['version'])
      if (!(position in (current.contacts ?? []))) throw new NotFoundError('Contact', position)
      const updated = await uow.patients.removeContact(id, position, (current.contacts ?? []).length)
      if (updated === null) throw new ConflictError('Patient', 'was changed by someone else since it was read', ['contacts'])
      return updated
    })
  }
}

